import { registerModule } from '../../core/lifecycle';

/*
 * Cards are now handled natively in src/components/cardbuilder/cardBuilder.js.
 * Keep this module registered as a no-op so old imports stay safe while we
 * remove MutationObserver-based card patching.
 */
function init() {
    document.documentElement.classList.add('ptv-native-cards');
}

function destroy() {
    document.documentElement.classList.remove('ptv-native-cards');
}

registerModule({
    name: 'cards',
    init,
    destroy
});
